[CmdletBinding()]
param([Parameter(Mandatory)][string]$ResultPath,[Parameter(Mandatory)][string]$ProjectRoot)
$ErrorActionPreference='Stop'
$issues=@();if(-not(Test-Path -LiteralPath $ResultPath -PathType Leaf)){$issues+='result-missing'}else{
 try{$r=Get-Content -Raw -Encoding UTF8 -LiteralPath $ResultPath|ConvertFrom-Json}catch{$issues+='result-invalid-json';$r=$null}
 if($r){$schema=Get-Content -Raw -Encoding UTF8 (Join-Path $ProjectRoot 'ES/Automation/Contracts/es-ai-abc-engineering-competition-result-v1.schema.json')|ConvertFrom-Json;$hash=(Get-FileHash -LiteralPath (Join-Path $ProjectRoot 'ES/Automation/Contracts/es-ai-abc-engineering-architecture-competition-v1.schema.json') -Algorithm SHA256).Hash.ToLowerInvariant();foreach($p in @('schemaVersion','contractId','contractHash','status','completionEligible','evidenceSummary','generationCount','generationHistory','paretoShortlist','winnerId','runtimeStatus')){if(-not $r.PSObject.Properties[$p]){$issues+="missing:$p"}};if([int]$r.schemaVersion -ne 1 -or [string]$r.contractId -ne [string]$schema.properties.contractId.const){$issues+='contract-identity-mismatch'};if(([string]$r.contractHash).ToLowerInvariant() -ne $hash){$issues+='contract-hash-mismatch'};if([int]$r.generationCount -ne 3 -or @($r.generationHistory).Count -lt 3){$issues+='generation-history-incomplete'};if(@($r.paretoShortlist).Count -lt 2 -or @($r.paretoShortlist).Count -gt 3){$issues+='pareto-range-invalid'};if($r.runtimeStatus -ne 'runtime-not-run'){$issues+='runtime-boundary-invalid'};if($r.status -eq 'completed' -and $r.completionEligible -ne $true){$issues+='completed-without-eligibility'};if($r.status -eq 'review-required' -and $r.completionEligible -eq $true){$issues+='review-state-eligibility-contradiction'};$e=$r.evidenceSummary;if($e){if($e.contractHashBound -ne $true){$issues+='evidence-contract-not-bound'};if([int]$e.counterfactualPositiveCount -gt [int]$e.eligibleCount){$issues+='evidence-count-inconsistent'};if($r.status -eq 'completed' -and ([int]$e.implementationEvidenceVerifiedCount -ne [int]$e.eligibleCount -or [int]$e.counterfactualPositiveCount -ne [int]$e.eligibleCount)){$issues+='completed-with-incomplete-evidence-count'}}else{$issues+='evidence-summary-missing'}}}
if($r -and $r.status -eq 'completed'){$e=$r.evidenceSummary;if($null -eq $e -or [int]$e.independentReplayVerifiedCount -ne [int]$e.eligibleCount){$issues+='completed-without-independent-replay'};if($null -eq $e -or [string]$e.providerScoreComparisonStatus -cne 'stable'){$issues+='completed-with-provider-score-instability'}}
$state=if($issues.Count -eq 0){'passed'}else{'failed'};[pscustomobject]@{status=$state;issues=$issues;resultPath=$ResultPath};if($issues.Count){exit 1}
